     4→function imgToBase64(url) {
     5→  return new Promise((resolve) => {
     6→    const img = new Image();
     7→    img.crossOrigin = 'anonymous';
     8→    img.onload = () => {
     9→      try {
    10→        const canvas = document.createElement('canvas');
    11→        canvas.width = img.naturalWidth;
    12→        canvas.height = img.naturalHeight;
    13→        const ctx = canvas.getContext('2d');
    14→        ctx.drawImage(img, 0, 0);
    15→        resolve(canvas.toDataURL('image/jpeg', 0.85));
    16→      } catch { resolve(url); }
    17→    };
    18→    img.onerror = () => resolve(url);
    19→    img.src = url + (url.includes('?') ? '&' : '?') + 't=' + Date.now();
    20→  });
    21→}
