    23→async function resolveImages(sections) {
    24→  const results = {};
    25→  const all = [];
    26→  sections.forEach(s => {
    27→    if (!s.images) return;
    28→    s.images.forEach(img => {
    29→      if (img.url) all.push({ key: img._id || img.url, url: img.url });
    30→    });
    31→  });
    32→  await Promise.all(all.map(async ({ key, url }) => {
    33→    results[key] = await imgToBase64(url);
    34→  }));
    35→  return results;
    36→}
