        </button>
        <p style={{ textAlign: 'center', fontSize: 11, color: '#94a3b8', marginTop: 8 }}>
          سيُعرض التقرير داخل النظام — ثم يمكنك طباعته أو تحميله
        </p>
      </div>
    </div>
  );
}

