            <ContentRow
              checked={opts.includeTTT} onChange={() => toggleOpt('includeTTT')}
              icon={<FiFileText size={18}/>}
              label="الملف الطبي التفصيلي (TTT File)"
              sublabel="بيانات الأسنان والخطة العلاجية"
            />
